                  Atualize os dados do seu salão
                </CardDescription>
              </CardHeader>
              <CardContent>
                {salonQuery.isLoading ? (
                  <div className="space-y-4">
                    {[...Array(4)].map((_, i) => (
                      <Skeleton key={i} className="h-10 w-full" />
                    ))}
                  </div>
                ) : salonQuery.data ? (
                  <form className="space-y-4">
