                        placeholder="email@example.com"
                      />
                    </div>
                    <div>
                      <label className="text-sm font-medium">Telefone</label>
                      <Input
                        value={specialistForm.phone}
                        onChange={(e) =>
                          setSpecialistForm({
                            ...specialistForm,
                            phone: e.target.value,
                          })
                        }
                        placeholder="(11) 99999-9999"
