export async function upsertUser(
  user: Partial<InsertUser> & { id: string }
): Promise<void> {
  if (!user.id) {
    throw new Error("User ID is required for upsert");
  }

  const db = await getDb();
  if (!db) {
    console.warn("[Database] Cannot upsert user: database not available");
    return;
  }

  try {
    const values: any = {
      id: user.id,
      name: user.name || "",
      email: user.email || "",
      password: user.password || "",
    };
    const updateSet: Record<string, unknown> = {};

    const textFields = ["name", "email"] as const;
    type TextField = (typeof textFields)[number];

    const assignNullable = (field: TextField) => {
      const value = user[field];
      if (value === undefined) return;
      const normalized = value ?? null;
      (values as any)[field] = normalized;
      updateSet[field] = normalized;
    };

    textFields.forEach(assignNullable);

    if (user.password !== undefined) {
      values.password = user.password;
      updateSet.password = user.password;
    }

    if (user.lastSignedIn !== undefined) {
      values.lastSignedIn = user.lastSignedIn;
      updateSet.lastSignedIn = user.lastSignedIn;
    }
    if (user.role === undefined) {
      if (user.id === ENV.ownerId) {
        user.role = "admin";
        values.role = "admin";
        updateSet.role = "admin";
      }
    }

    if (Object.keys(updateSet).length === 0) {
      updateSet.lastSignedIn = new Date();
    }

    try {
      // Primeiro tenta atualizar - se o usuário já existir
      const result = await db
        .update(users)
        .set(updateSet)
        .where(eq(users.id, user.id))
        .returning();

      // Se não atualizou nenhuma linha, então o usuário não existe, então inserimos
      if (result.length === 0) {
        await db.insert(users).values(values);
      }
    } catch (error) {
      console.error(
        "[Database] Failed to upsert user with PostgreSQL approach:",
        error
      );
      throw error;
    }
  } catch (error) {
    console.error("[Database] Failed to upsert user:", error);
    throw error;
  }
}

