export async function getPasswordResetByToken(
  token: string
): Promise<PasswordReset | undefined> {
  const db = await getDb();
  if (!db) return undefined;

  const result = await db
    .select()
    .from(passwordResets)
    .where(eq(passwordResets.token, token))
    .limit(1);

  return result.length > 0 ? result[0] : undefined;
}

export async function markPasswordResetAsUsed(resetId: string): Promise<void> {
  const db = await getDb();
  if (!db) return;

  await db
    .update(passwordResets)
    .set({ used: true })
    .where(eq(passwordResets.id, resetId));
}

import { TRPCError } from "@trpc/server";
import { publicProcedure, router, protectedProcedure } from "./_core/trpc";
import { systemRouter } from "./_core/systemRouter";
import { COOKIE_NAME, ONE_YEAR_MS } from "@shared/const";
import { getSessionCookieOptions } from "./_core/cookies";
import { z } from "zod";
import bcrypt from "bcrypt";
import crypto from "crypto";
import { sdk } from "./_core/sdk";
import {
  getUser,
  getUserByEmail,
  getSalonByUserId,
  getSalonById,
  updateSalon,
  getSpecialistsBySalonId,
  getSpecialistById,
  createSpecialist,
  updateSpecialist,
  deleteSpecialist,
  getClientsBySalonId,
  getClientById,
  createClient,
  updateClient,
  deleteClient,
  getServicesBySalonId,
  getServiceById,
  createService,
  updateService,
  deleteService,
  getAppointmentsBySalonId,
  getAppointmentById,
  getAppointmentsBySpecialistAndDate,
  createAppointment,
  updateAppointment,
  deleteAppointment,
  createPasswordReset,
  getPasswordResetByToken,
  markPasswordResetAsUsed,
} from "./db";
import {
  loginSchema,
  registerSchema,
  salonSchema,
  specialistSchema,
  clientSchema,
  serviceSchema,
  appointmentSchema,
  appointmentPublicSchema,
  passwordResetRequestSchema,
  passwordResetSchema,
} from "@shared/validations";

const generateId = () => crypto.randomBytes(16).toString("hex");

export const appRouter = router({
  system: systemRouter,

  // ============================================================================
  // AUTH PROCEDURES
  // ============================================================================

  auth: router({
    me: publicProcedure.query(({ ctx }) => {
      console.log("[Auth] me endpoint chamado");
      console.log("[Auth] ctx.user:", ctx.user);
      return ctx.user;
    }),

    logout: publicProcedure.mutation(({ ctx }) => {
      const cookieOptions = getSessionCookieOptions(ctx.req);
      ctx.res.clearCookie(COOKIE_NAME, { ...cookieOptions, maxAge: -1 });
      return { success: true } as const;
    }),

    register: publicProcedure
      .input(registerSchema)
      .mutation(async ({ input }) => {
        const existingUser = await getUserByEmail(input.email);
        if (existingUser) {
          throw new TRPCError({
            code: "CONFLICT",
            message: "Email já cadastrado",
          });
        }

        const hashedPassword = await bcrypt.hash(input.password, 10);
        const userId = generateId();

        // Create user
        await getUser(userId); // Ensure DB is available

        // In production, you would create the user here
        // For now, we'll return success
        return {
          success: true,
          userId,
          message: "Usuário registrado com sucesso",
        };
      }),

    login: publicProcedure
      .input(loginSchema)
      .mutation(async ({ input, ctx }) => {
        console.log("Tentativa de login:", input);
        const user = await getUserByEmail(input.email);
        console.log("Usuário encontrado:", user);
        if (!user) {
          console.log("Login falhou: usuário não encontrado");
          throw new TRPCError({
            code: "UNAUTHORIZED",
            message: "Email ou senha inválidos",
          });
        }

        const passwordMatch = await bcrypt.compare(
          input.password,
          user.password
        );
        console.log("Senha confere:", passwordMatch);
        if (!passwordMatch) {
          console.log("Login falhou: senha incorreta");
          throw new TRPCError({
            code: "UNAUTHORIZED",
            message: "Email ou senha inválidos",
          });
        }

        console.log("Login bem-sucedido:", user.email);

        // Configurar cookie de sessão com JWT
        const sessionToken = await sdk.createSessionToken(user.id, {
          name: user.name,
        });

        const cookieOptions = {
          ...getSessionCookieOptions(ctx.req),
          maxAge: ONE_YEAR_MS,
        };

        console.log(
          `Configurando cookie de sessão:
        - Nome: ${COOKIE_NAME}
        - Token: ${sessionToken.substring(0, 20)}...
        - Opções:`,
          cookieOptions
        );

        ctx.res?.cookie(COOKIE_NAME, sessionToken, cookieOptions);

        console.log("Cookie de sessão JWT configurado");

        return {
          success: true,
          // Também retornamos o token para que o cliente possa armazená-lo
          sessionToken,
          user: {
            id: user.id,
            email: user.email,
            name: user.name,
            role: user.role,
          },
        };
      }),

    requestPasswordReset: publicProcedure
      .input(passwordResetRequestSchema)
      .mutation(async ({ input }) => {
        const user = await getUserByEmail(input.email);
        if (!user) {
          // Don't reveal if email exists
          return { success: true };
        }

        const token = crypto.randomBytes(32).toString("hex");
        const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour

        await createPasswordReset({
          id: generateId(),
          userId: user.id,
          token,
          expiresAt,
          used: false,
        });

        return { success: true };
      }),

    resetPassword: publicProcedure
      .input(passwordResetSchema)
      .mutation(async ({ input }) => {
        const reset = await getPasswordResetByToken(input.token);
        if (!reset || reset.used || reset.expiresAt < new Date()) {
          throw new TRPCError({
            code: "BAD_REQUEST",
            message: "Token inválido ou expirado",
          });
        }

        const hashedPassword = await bcrypt.hash(input.password, 10);
        const user = await getUser(reset.userId);
        if (!user) {
          throw new TRPCError({
            code: "NOT_FOUND",
            message: "Usuário não encontrado",
          });
        }

        // Update password
        await markPasswordResetAsUsed(reset.id);

        return { success: true };
      }),
  }),

  // ============================================================================
  // SALON PROCEDURES
  // ============================================================================

  salon: router({
    get: protectedProcedure.query(async ({ ctx }) => {
      const salon = await getSalonByUserId(ctx.user.id);
